class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        ListNode* dummy = new ListNode(0, head);
        ListNode* prev = dummy;
        while (true) {
            ListNode* check = prev;
            for (int s = 0; s < k && check; s++) check = check->next;
            if (!check) break;
            ListNode* cur = prev->next;
            for (int s = 1; s < k; s++) {
                ListNode* nxt = cur->next;
                cur->next = nxt->next;
                nxt->next = prev->next;
                prev->next = nxt;
            }
            prev = cur;
        }
        return dummy->next;
    }
};
